head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.vIsurCd = "";
scwin.vLIST_STAT_CD = "Y";
// 호출메뉴ID를 식별하기 위한 함수사용
// 세션정보를 얻기위한 함수사용
// 상장관련공통함수
scwin.fr_SecuGrpId = SECUGRP_ID_EN;
scwin.fr_MktId = $c.lce.fn_getMktId(); // 시장구분코드(유가, 코스닥) 전체), 기준은 로그인 사용자의 부서 소속을 기준으로 한다.

scwin.fn_GetPar, scwin.fn_SetPar;

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name onpageload
 * @description 화면 로딩 시 초기 처리 — init 순차 호출
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.onpageload = async function() {
    try {
        $c.libRoundPanel.PanelToGroupBox(pan_Cnd);
        $c.libRoundPanel.PanelToGroupBox(pan_Cnd2);
        $c.libRoundPanel.PanelToGroupBox(pan_Cnd3);
        $c.libRoundPanel.PanelToGroupBox(pan_Cnd4);
        await scwin.getIsurcode();
        rdo_1_1.setValue("1");
        const vEaryRedmpt = $c.stf.getQuery(frame.srcUrl, "isEaryRedmpt");
        if (vEaryRedmpt === "Y") {
            img_Etnlist.setSelectedTabIndex(3);
            await scwin.newCreateFrame3();
        } else {
            img_Etnlist.setSelectedTabIndex(1);
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08051.onpageload" });
    }
};

/**
 * @method
 * @name onpageunload
 * @description 화면 언로드 시 정리 처리
 * @returns {void}
 * @hidden N
 */
scwin.onpageunload = function() {
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name img_Etnlist_OnSelChanged
 * @description img Etnlist On Sel Changed 처리
 * @param {*} nIndex nIndex
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Etnlist_OnSelChanged = async function(nIndex) {
    try {
        if (nIndex === 1) {
            rdo_1_1.setValue("1");
            rdo_1_2.setValue("2");
            txb_ISU_CD.setValue("");
            txb_ISU_NM.setValue("");
            cmb_ISUR_CD.setSelectedIndex(0);
            // fn_search();

        } else if (nIndex === 2) // ko_jackal_10.06.15

        {
            await scwin.search2();
        } else if (nIndex === 3) {
            await scwin.search3();
        } else if (nIndex === 4) {
            await scwin.search4();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08051.img_Etnlist_OnSelChanged" });
    }
};

/**
 * @method
 * @name dts_OnLoadError
 * @description dts 로드 오류 처리(레거시 Gauce 이벤트명 — 화면 내부 호출용)
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.dts_OnLoadError = async function() {
    try {
        await $c.win.alert(dts);
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08051.dts_OnLoadError" });
    }
};

