/**
 * @method
 * @name img_Regist_onclick
 * @description 「신규」 클릭 이벤트
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.img_Regist_onclick = async function() {
    try {
        if (rdo_1_1.getValue() === "1") {
            if (txb_ISU_CD.getValue() === "") {
                await $c.win.alert($c.stf.getMessageParam("MSG-0015", ""));
                return true;
            }
        }
        scwin.fn_GetPar = scwin.getParNew;
        scwin.fn_SetPar = undefined;
        if (rdo_1_2.getValue() === "1") {
            await scwin.newCreateFrame();
        } else {
            await scwin.newpreCreateFrame();
        }
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF08051.img_Regist_onclick" });
    }
};

