 */
scwin.img_Excel_onclick = async function() {
    try {
        $c.stf.doLogSave("ULDSTF08051.xml", SCREN_PROCS_TP_CD_07);
        if (dts.getRowCount() > 0) {
            $c.data.downloadGridViewExcel(grd, {fileName: $c.lce.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + "상장폐지내역", type: "8"});
        } else {
            await $c.win.alert(NO_EXCEL_DATA);
        }
    } catch (ex) {
