///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name search
 * @description jackal_11.05.12 상장종목 여부 체크 추가
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.search = async function() {
    if (rdo_1_1.getValue() === "1") {
        url += "&DIV_IDX=" + DIV_IDX_ETN_DELLIST_LIST_ISU + "&TRS_IDX=" + TRS_IDX_SELECT + "&ISU_CD=" + txb_ISU_CD.getValue();
    } else if (rdo_1_2.getValue() === "1") {
        if (cmb_ISUR_CD.getSelectedIndex() === 0) {
            url += "&DIV_IDX=" + DIV_IDX_ETN_DELLIST_LIST_ALL + "&TRS_IDX=" + TRS_IDX_SELECT;
        } else {
            url += "&DIV_IDX=" + DIV_IDX_ETN_DELLIST_LIST_CORP + "&TRS_IDX=" + TRS_IDX_SELECT + "&ISUR_CD=" + cmb_ISUR_CD.BindColVal;
        }
    }
    url += "&SCREN_ID=" + "ULDSTF08051.xml" + "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01;

    // var url = "/Delisting.do?method=searchDelList" +
    //              "&DIV_IDX="+DIV_IDX_DELLIST_LIST + "&TRS_IDX="+TRS_IDX_SELECT + "&ISUR_CD=" + cmb_ISUR_CD.BindColVal ;
    // url += "&SCREN_ID=" + vScrenID;
    // url += "&SCREN_PROCES_TP_CD=" + SCREN_PROCS_TP_CD_01 ;
    const sbmOptions = {
        id : "sbm_dts",
        action : "/etn/EtnMktAct.do",
        ref : "",
        target : "dts=body.content",
        isProcessMsg : false
    };

    const sbmRtn = await $c.sbm.executeDynamic(sbmOptions);
    // TODO Stage2: sbmRtn 응답 처리 로직 작성 (구 submitDoneHandler 자리)

};

