/**
 * @method
 * @name newCreateFrame
 * @description new Create Frame 처리
 * @returns {Promise<void>}
 * @hidden N
 */
scwin.newCreateFrame = async function() {
    const options = {
        id: "ULDSTF08052_new",
        title: $c.lce.fn_getSecuGrpNm(scwin.fr_SecuGrpId) + " 상장폐지",
        type: "browserPopup",
        width: "740px",
        height: "450px",
        callbackFn: "scwin.popupCallback"
    };

    $c.win.openPopup("../etn/ULDSTF08052_new.gfm", options);
    await scwin.search(); // 다이얼로그 창이 닫히면 조회를 보낸다.

};

