/**
 * @method
 * @name changeRadioBtn
 * @description change Radio Btn 처리
 * @param {Number} idx idx
 * @returns {void}
 * @hidden N
 */
scwin.changeRadioBtn = function(idx) {
    if (idx === "1") {
        cmb_ISUR_CD.setSelectedIndex(0);
        rdo_1_1.setValue("1");
        rdo_1_2.setValue("2");
    } else if (idx === "2") {
        txb_ISU_CD.setValue("");
        txb_ISU_NM.setValue("");
        rdo_1_1.setValue("2");
        rdo_1_2.setValue("1");
    }
};
